import cdflib,glob
for f in sorted(glob.glob('/mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data/raw/masters/*.cdf')):
  c=cdflib.CDF(f)
  info=c.cdf_info()
  ev=[v for v in info.zVariables if v.lower().startswith('epoch')][:1]
  for v in ev:
    a=c.varattsget(v); print('==',f.split('/')[-1],v,{k:str(a[k])[:300] for k in a if k in ('CATDESC','VAR_NOTES','FIELDNAM','DELTA_PLUS_VAR','DELTA_MINUS_VAR','TIME_BASE','BIN_LOCATION','SCALETYP')})
  g=c.globalattsget(); print('   TEXT:', str(g.get('TEXT',''))[:1200].replace('\n',' '))
"",
  "description": "Check Epoch conventions in master CDFs"
}

